import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ---------- Custom CUDA kernels for LayerNorm (FP32) ----------

# Kernel 1: compute mean per element (naive)
elementmean_kernel_cpp = """
#include <torch/extension.h>

__global__ void compute_mean_kernel(const float* x, float* mean, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        mean[idx] = x[idx];
    }
}
"""

# Kernel 2: compute variance
elementvar_kernel_cpp = """
__global__ void compute_var_kernel(const float* x, const float* mean, float* var, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        float diff = x[idx] - mean[idx];
        var[idx] = diff * diff;
    }
}
"""

# Kernel 3: normalize
elementnorm_kernel_cpp = """
__global__ void normalize_kernel(const float* x, const float* mean, const float* var, float* out, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        float val = x[idx];
        out[idx] = (val - mean[idx]) / sqrtf(var[idx] + 1e-5f);
    }
}
"""

# ---------- Custom CUDA function layer_norm_cuda ----------
layer_norm_cuda_source = """
torch::Tensor layer_norm_cuda(torch::Tensor x) {
    auto total_elements = x.numel();
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Compute mean
    float* mean_ptr = new float(total_elements);
    elementmean_kernel_cpp<<<num_blocks, block_size>>>(x.data_ptr<float()>, mean_ptr, total_elements);

    // Compute variance
    float* var_ptr = new float(total_elements);
    elementvar_kernel_cpp<<<num_blocks, block_size>>>(x.data_ptr<float()>, mean_ptr, var_ptr, total_elements);

    // Normalize
    float* out_ptr = new float(total_elements);
    normalize_kernel<<<num_blocks, block_size>>>(x.data_ptr<float()>, mean_ptr, var_ptr, out_ptr, total_elements);

    delete[] mean_ptr;
    delete[] var_ptr;
    delete[] out_ptr;

    return torch::from_blob(out_ptr, total_elements).view(total_elements).clone().cuda();
}
"""

# ---------- Element-wise addition (reuse from example) ----------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

